/** Clubs in one league, in the order this file lists them. */
export function clubsInLeague(league: string): Club[] {
  return CLUBS.filter(c => c.league === league)
}

/** How many clubs a league has, without materialising the list. */
export function clubCount(league: string): number {
  let n = 0
  for (const c of CLUBS) if (c.league === league) n++
  return n
}
